// Tavily検索結果を整形
const tavilyData = $input.item.json;
const companyInfo = $('検索クエリを生成').first().json;

let formattedResult = '';

// ヘッダー
formattedResult += `# ${companyInfo.companyName} 企業情報\n\n`;
formattedResult += `検索日時: ${new Date().toISOString()}\n\n`;

// AI要約
if (tavilyData.answer) {
  formattedResult += `## AI要約\n\n${tavilyData.answer}\n\n`;
}

// 検索結果
if (tavilyData.results && tavilyData.results.length > 0) {
  formattedResult += `## 検索結果（${tavilyData.results.length}件）\n\n`;

  tavilyData.results.forEach((result, index) => {
    formattedResult += `### ${index + 1}. ${result.title || '(タイトルなし)'}\n`;
    if (result.content) {
      formattedResult += `${result.content}\n\n`;
    }
    if (result.url) {
      formattedResult += `🔗 ${result.url}\n\n`;
    }
    formattedResult += '---\n\n';
  });
}

// ソースURLリスト
const sources = tavilyData.results?.map(r => ({
  title: r.title,
  url: r.url,
  score: r.score
})) || [];

return [{
  json: {
    companyName: companyInfo.companyName,
    ticker: companyInfo.ticker,
    answer: tavilyData.answer || '',
    formattedResult,
    resultCount: tavilyData.results?.length || 0,
    sources,
    rawResults: tavilyData.results || []
  }
}];
